+/** Compares sold recipe quantities with all consumed stock in an inclusive UTC day range. */
+export function varianceReport(store, from, to) {
+  if (from > to) throw new AppError("bad_request", { reason: "from must be on or before to" });
+  const totals = new Map();
+  function add(itemId, field, qty) {
+    if (!totals.has(itemId)) totals.set(itemId, { itemId, theoretical: 0, actual: 0 });
+    totals.get(itemId)[field] += Math.round(qty * 1000);
+  }
+  function inRange(at) {
+    const day = dayOf(at);
+    return day >= from && day <= to;
+  }
+  for (const sale of store.data.sales) {
+    if (!inRange(sale.soldAt)) continue;
+    for (const ingredient of sale.ingredients) add(ingredient.itemId, "theoretical", ingredient.qty);
+  }
+  const items = new Map(store.data.batches.map((batch) => [batch.id, batch.itemId]));
+  for (const movement of store.data.movements) {
+    if (movement.type === "consume" && inRange(movement.at))
+      add(items.get(movement.batchId), "actual", movement.qty);
+  }
+  return [...totals.values()]
+    .filter(({ theoretical, actual }) => theoretical > 0 || actual > 0)
+    .sort((a, b) => a.itemId - b.itemId)
+    .map(({ itemId, theoretical, actual }) => ({
+      itemId, theoretical: theoretical / 1000, actual: actual / 1000, variance: (actual - theoretical) / 1000,
+    }));
+}
