diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..df8a51a
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,66 @@
+import { memoryStore } from "../db/store.js";
+import { isDate } from "../dates.js";
+import { consume } from "../domain/batches.js";
+import { getDish } from "../domain/menu.js";
+import { getRecipe, scaled } from "../domain/recipes.js";
+import { AppError } from "../errors.js";
+import { parseCsv } from "./csv.js";
+
+const columns = ["ticket", "soldAt", "dishId", "qty"];
+const csvLine = /^(?:"(?:[^"]|"")*"|[^",]*)(?:,(?:"(?:[^"]|"")*"|[^",]*))*$/;
+const instant = /^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d+)?)?(?:Z|[+-](?:[01]\d|2[0-3]):[0-5]\d)$/;
+
+function invalid(row, reason) {
+  return new AppError("bad_request", { reason: `row ${row}: ${reason}` });
+}
+
+/** Imports a complete till file, counting new tickets and portions sold. */
+export function importSales(store, csv) {
+  if (typeof csv !== "string") throw invalid(1, "csv must be text");
+  const staged = memoryStore(store.data);
+  const existing = new Set(store.data.sales.map((sale) => sale.ticket));
+  const tickets = new Set();
+  let dishes = 0;
+  let header;
+  for (const [index, line] of csv.split(/\r?\n/).entries()) {
+    if (!line.trim()) continue;
+    const row = index + 1;
+    if (!csvLine.test(line)) throw invalid(row, "malformed CSV");
+    const fields = parseCsv(line)[0].map((field) => field.trim());
+    if (!header) {
+      if (fields.length !== columns.length || !columns.every((key) => fields.includes(key)))
+        throw invalid(row, "expected ticket,soldAt,dishId,qty");
+      header = fields;
+      continue;
+    }
+    if (fields.length !== header.length) throw invalid(row, "expected four fields");
+    const values = Object.fromEntries(header.map((key, i) => [key, fields[i]]));
+    const { ticket, soldAt } = values;
+    const dishId = Number(values.dishId);
+    const qty = Number(values.qty);
+    if (!ticket) throw invalid(row, "missing ticket");
+    if (!instant.test(soldAt) || !isDate(soldAt.slice(0, 10))) throw invalid(row, "invalid soldAt");
+    if (!/^\d+$/.test(values.qty) || !Number.isSafeInteger(qty) || qty < 1) throw invalid(row, "invalid qty");
+    if (!/^\d+$/.test(values.dishId) || !Number.isSafeInteger(dishId) || dishId < 1) throw invalid(row, "invalid dishId");
+    try {
+      const dish = getDish(staged, dishId);
+      if (existing.has(ticket)) continue;
+      const at = new Date(soldAt).toISOString();
+      const ingredients = scaled(getRecipe(staged, dish.recipeId), qty);
+      for (const need of ingredients) {
+        if (need.qty > 0) consume(staged, need.itemId, need.qty, { at, ref: `sale:${ticket}` });
+      }
+      staged.data.sales.push({ id: staged.nextId("sale"), ticket, soldAt: at, dishId, qty, ingredients });
+    } catch (error) {
+      if (!(error instanceof AppError)) throw error;
+      if (error.code === "not_enough_stock")
+        throw new AppError("sale_stock_shortage", { ...error.params, row });
+      throw invalid(row, error.code === "not_found" ? "unknown dish or recipe" : error.code);
+    }
+    tickets.add(ticket);
+    dishes += qty;
+  }
+  if (!header) throw invalid(1, "missing header");
+  store.data = staged.data;
+  return { tickets: tickets.size, dishes };
+}
